        className: "language-java",
        children: "import org.apache.poi.ss.usermodel.Row;\nimport org.apache.poi.xssf.streaming.SXSSFWorkbook;\n\nimport java.io.IOException;\nimport java.io.OutputStream;\nimport java.util.List;\n\npublic class ExcelErrorReportWriter {\n\n    public void write(OutputStream output, List<ExcelRowError> errors) {\n        try (SXSSFWorkbook workbook = new SXSSFWorkbook(100)) {\n            workbook.setCompressTempFiles(true);\n\n            var sheet = workbook.createSheet(\"Errors\");\n\n            Row header = sheet.createRow(0);\n            header.createCell(0).setCellValue(\"Sheet\");\n            header.createCell(1).setCellValue(\"Row\");\n            header.createCell(2).setCellValue(\"Cell\");\n            header.createCell(3).setCellValue(\"Column\");\n            header.createCell(4).setCellValue(\"Raw Value\");\n            header.createCell(5).setCellValue(\"Error Code\");\n            header.createCell(6).setCellValue(\"Message\");\n\n            int rowIndex = 1;\n\n            for (ExcelRowError error : errors) {\n                Row row = sheet.createRow(rowIndex++);\n                row.createCell(0).setCellValue(nullToBlank(error.sheetName()));\n                row.createCell(1).setCellValue(error.rowNumber());\n                row.createCell(2).setCellValue(nullToBlank(error.cellAddress()));\n                row.createCell(3).setCellValue(nullToBlank(error.columnName()));\n                row.createCell(4).setCellValue(nullToBlank(error.rawValue()));\n                row.createCell(5).setCellValue(nullToBlank(error.errorCode()));\n                row.createCell(6).setCellValue(nullToBlank(error.message()));\n            }\n\n            workbook.write(output);\n            workbook.dispose();\n        } catch (IOException e) {\n            throw new ExcelProcessingException(\"Failed to write Excel error report\", e);\n        }\n    }\n\n    private String nullToBlank(String value) {\n        return value == null ? \"\" : value;\n    }\n}\n"
