        className: "language-java",
        children: "import org.apache.pdfbox.Loader;\nimport org.apache.pdfbox.pdmodel.PDDocument;\nimport org.apache.pdfbox.text.PDFTextStripper;\n\nimport java.nio.file.Path;\nimport java.util.ArrayList;\nimport java.util.List;\n\npublic class PdfPageTextExtractor {\n\n    public List<PdfPageText> extractByPage(Path pdfPath, PdfExtractionPolicy policy) {\n        try (PDDocument document = Loader.loadPDF(pdfPath.toFile())) {\n            int pageCount = document.getNumberOfPages();\n\n            if (pageCount > policy.maxPages()) {\n                throw new PdfRejectedException(\n                        \"TOO_MANY_PAGES\",\n                        \"PDF exceeds maximum page limit: \" + policy.maxPages()\n                );\n            }\n\n            PDFTextStripper stripper = new PDFTextStripper();\n            stripper.setSortByPosition(true);\n\n            List<PdfPageText> pages = new ArrayList<>();\n            long totalChars = 0;\n\n            for (int page = 1; page <= pageCount; page++) {\n                stripper.setStartPage(page);\n                stripper.setEndPage(page);\n\n                String text = stripper.getText(document);\n                String normalized = normalizeText(text);\n\n                totalChars += normalized.length();\n\n                if (totalChars > policy.maxExtractedChars()) {\n                    throw new PdfRejectedException(\n                            \"EXTRACTED_TEXT_TOO_LARGE\",\n                            \"Extracted text exceeds maximum character limit\"\n                    );\n                }\n\n                boolean likelyScanned = normalized.isBlank();\n                double qualityScore = estimateTextQuality(normalized);\n\n                pages.add(new PdfPageText(\n                        page,\n                        normalized,\n                        normalized.length(),\n                        likelyScanned,\n                        qualityScore\n                ));\n            }\n\n  