        children: "public class JobFailureHandler {\n\n    private final RetryPolicy retryPolicy;\n    private final FileProcessingJobRepository repository;\n\n    public void handleFailure(\n            FileProcessingJob job,\n            Throwable error\n    ) {\n        FailureClassification classification = classify(error);\n\n        if (!classification.retryable()) {\n            repository.markFailed(\n                    job.id(),\n                    classification.code(),\n                    classification.safeMessage()\n            );\n            return;\n        }\n\n        if (job.attemptCount() >= job.maxAttempts()) {\n            repository.markFailed(\n                    job.id(),\n                    \"MAX_ATTEMPTS_EXCEEDED\",\n                    \"Job failed after maximum retry attempts\"\n            );\n            return;\n        }\n\n        java.time.Instant nextAttemptAt = java.time.Instant.now()\n                .plus(retryPolicy.delayForAttempt(job.attemptCount()));\n\n        repository.scheduleRetry(\n                job.id(),\n                classification.code(),\n                classification.safeMessage(),\n                nextAttemptAt\n        );\n    }\n\n    private FailureClassification classify(Throwable error) {\n        if (error instanceof TransientStorageException) {\n            return new FailureClassification(true, \"STORAGE_TEMPORARILY_UNAVAILABLE\", \"Storage temporarily unavailable\");\n        }\n\n        if (error instanceof ValidationRejectedException e) {\n            return new FailureClassification(false, e.code(), e.getMessage());\n        }\n\n        return new FailureClassification(false, \"JOB_FAILED\", \"Job failed\");\n    }\n}\n"
